using System;using System.Collections.Generic;public class Solution{public int MaxSumSubmatrix(int[][]a,int k){int m=a.Length,n=a[0].Length,b=int.MinValue;for(int top=0;top<m;top++){int[]s=new int[n];for(int bot=top;bot<m;bot++){for(int c=0;c<n;c++)s[c]+=a[bot][c];var p=new SortedSet<int>{0};int cur=0;foreach(int x in s){cur+=x;var view=p.GetViewBetween(cur-k,int.MaxValue);if(view.Count>0)b=Math.Max(b,cur-view.Min);p.Add(cur);}}}return b;}}
